private fun updateSelectedConstructionTable(construction: IConstruction) {
    val cityConstructions = cityView.constructions

    //val selectedConstructionTable = Table()
    selectedConstructionTable.run {
        pad(10f)

        add(ImageGetter.getConstructionPortrait(construction.name, 50f).apply {
            val link = (construction as? IRulesetObject)?.makeLink() ?: return@apply
            if (link.isEmpty()) return@apply
            touchable = Touchable.enabled
            this.onClick {
                cityScreen.openCivilopedia(link)
            }
        }).pad(5f)

        var buildingText = construction.name.tr(hideIcons = true)
        val specialConstruction = PerpetualConstruction.perpetualConstructionsMap[construction.name]

        buildingText += specialConstruction?.let { cityView.getProductionTooltip(it) }
                ?: cityConstructions.getTurnsToConstructionString(construction)

        add(Label(buildingText, BaseScreen.skin)).expandX().row()  // already translated

        val description = when (construction) {
            is BaseUnit -> cityView.getUnitDescription(construction)
            is Building -> cityView.getBuildingDescription(construction)
            is StatConversion -> construction.description.replace("[rate]", "[${cityView.getConversionRate(construction)}]").tr()
            is PerpetualConstruction -> construction.description.tr()
            else -> ""  // Should never happen
        }

        val descriptionLabel = Label(description, BaseScreen.skin)  // already translated
        descriptionLabel.wrap = true
        add(descriptionLabel).colspan(2).width(cityScreen.stage.width / if(cityScreen.isCrampedPortrait()) 3 else 4)

/** Translate a [String] and make a [TextButton] widget from it */
fun String.toTextButton(style: TextButtonStyle? = null, hideIcons: Boolean = false): TextButton {
    val text = this.tr(hideIcons)
    return if (style == null) TextButton(text, BaseScreen.skin) else TextButton(text, style)
}

/** Translate a [String] and make a [Label] widget from it with a specified font color and size */
fun String.toLabel(fontColor: Color = Color.WHITE,
                    fontSize: Int = Constants.defaultFontSize,
                    alignment: Int = Align.left,
                    hideIcons: Boolean = false): Label {
    // We don't want to use setFontSize and setFontColor because they set the font,
    //  which means we need to rebuild the font cache which means more memory allocation.
    var labelStyle = BaseScreen.skin.get(Label.LabelStyle::class.java)
    if (fontColor != Color.WHITE || fontSize != Constants.defaultFontSize) { // if we want the default we don't need to create another style
        labelStyle = Label.LabelStyle(labelStyle) // clone this to another
        labelStyle.fontColor = fontColor
        if (fontSize != Constants.defaultFontSize) labelStyle.font = Fonts.font
    }
    val translatedText = this.tr(hideIcons) 
    return Label(translatedText, labelStyle).apply {
        setFontScale(fontSize / Fonts.ORIGINAL_FONT_SIZE)
        setAlignment(alignment)
    }
}

/** Sets the font size on a [Label] and returns it to allow chaining */
fun Label.setFontSize(size: Int): Label {
    style = Label.LabelStyle(style)
    style.font = Fonts.font
    @Suppress("UsePropertyAccessSyntax") setStyle(style)
    setFontScale(size / Fonts.ORIGINAL_FONT_SIZE)
    return this
